contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > c.MinDeposit());
        require(tx.origin != address(this));
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        // The deposit must be credited to the calling account itself, so the
        // caller's withdrawable balance grows by the full deposited amount.
        assert(c.balances(address(this)) >= amount);
    }
    receive() external payable {}
}

